import type { ComponentProps, ReactElement } from "react";
import Animated from "react-native-reanimated";
import { TextClassProvider, useTextClass } from "./text.context";
import {
	canNestText,
	resolveTextClass,
	TEXT_MAX_FONT_SIZE_MULTIPLIER,
	type TextAlign,
	type TextColor,
	type TextSize,
	type TextTransform,
	type TextVariant,
	type TextWeight,
} from "./text.variants";

export type TextProps = Omit<ComponentProps<typeof Animated.Text>, "className"> & {
	/** The named role. Omit it and the text inherits, falling back to the base treatment. */
	variant?: TextVariant;
	/** A step on the type scale. Beats the variant's own size. */
	size?: TextSize;
	weight?: TextWeight;
	/**
	 * A page-level text colour. For text drawn on a coloured surface — a button,
	 * a badge — use a `className`: that mapping belongs to the surface.
	 */
	color?: TextColor;
	align?: TextAlign;
	transform?: TextTransform;
	/**
	 * Merged last, so it beats every named axis and anything inherited.
	 *
	 * An arbitrary font size has to be written as a length — `text-[17px]` or
	 * `text-(length:--x)`. A bare `text-[var(--x)]` is ambiguous to
	 * tailwind-merge, which files it under colour, so it will not override the
	 * inherited size.
	 */
	className?: string;
};

/** A preset's props: every axis except the role it already is. */
export type TextPresetProps = Omit<TextProps, "variant">;

function TextRoot({
	align,
	children,
	className,
	color,
	maxFontSizeMultiplier = TEXT_MAX_FONT_SIZE_MULTIPLIER,
	size,
	transform,
	variant,
	weight,
	...props
}: TextProps): ReactElement {
	const inherited = useTextClass();

	const resolved = resolveTextClass({
		align,
		className,
		color,
		inherited,
		isNested: inherited !== undefined,
		size,
		transform,
		variant,
		weight,
	});

	const element = (
		<Animated.Text className={resolved} maxFontSizeMultiplier={maxFontSizeMultiplier} {...props}>
			{children}
		</Animated.Text>
	);

	// A string or number child has no descendant that could read the context, so
	// the provider is skipped rather than rendered once per label. `Text` is the
	// most-instantiated component in an app; this is the common case.
	return canNestText(children) ? <TextClassProvider value={resolved}>{element}</TextClassProvider> : element;
}

/**
 * A screen's one hero line — 30pt bold.
 *
 * Announced as a heading, so a screen reader's rotor stops on it rather than
 * reading it as one more line of body copy.
 */
function TextDisplay(props: TextPresetProps): ReactElement {
	return <TextRoot accessibilityRole="header" variant="display" {...props} />;
}
TextDisplay.displayName = "DelacourUI.Text.Display";

/** A screen or card title — 24pt bold. Announced as a heading. */
function TextTitle(props: TextPresetProps): ReactElement {
	return <TextRoot accessibilityRole="header" variant="title" {...props} />;
}
TextTitle.displayName = "DelacourUI.Text.Title";

/** A section heading — 20pt semibold. Announced as a heading. */
function TextHeader(props: TextPresetProps): ReactElement {
	return <TextRoot accessibilityRole="header" variant="header" {...props} />;
}
TextHeader.displayName = "DelacourUI.Text.Header";

/**
 * The secondary line under a title — 18pt on the muted token.
 *
 * Deliberately not a fourth heading level, and deliberately not announced as
 * one: it restates the title rather than introducing a new section.
 */
function TextSubheader(props: TextPresetProps): ReactElement {
	return <TextRoot variant="subheader" {...props} />;
}
TextSubheader.displayName = "DelacourUI.Text.Subheader";

/**
 * A block of prose — 16pt on the foreground token.
 *
 * The same treatment a bare `<Text>` already renders. It exists so a paragraph
 * *reads* as one at the call site, the way `Button.Label` exists even though a
 * bare string child already produces one.
 */
function TextParagraph(props: TextPresetProps): ReactElement {
	return <TextRoot variant="paragraph" {...props} />;
}
TextParagraph.displayName = "DelacourUI.Text.Paragraph";

/** A control label or compact UI string — 14pt medium. */
function TextLabel(props: TextPresetProps): ReactElement {
	return <TextRoot variant="label" {...props} />;
}
TextLabel.displayName = "DelacourUI.Text.Label";

/** Supporting copy under a label or a title — 14pt on the muted token. */
function TextCaption(props: TextPresetProps): ReactElement {
	return <TextRoot variant="caption" {...props} />;
}
TextCaption.displayName = "DelacourUI.Text.Caption";

/** An eyebrow above a section — 12pt semibold, uppercase, muted. */
function TextOverline(props: TextPresetProps): ReactElement {
	return <TextRoot variant="overline" {...props} />;
}
TextOverline.displayName = "DelacourUI.Text.Overline";

/**
 * Inline emphasis by weight.
 *
 * Emits `font-semibold` and nothing else, so mid-paragraph it comes out at the
 * surrounding text's size and colour. Standing on its own it falls back to the
 * base treatment — React Native's own default colour does not follow the theme.
 */
function TextStrong(props: TextPresetProps): ReactElement {
	return <TextRoot variant="strong" {...props} />;
}
TextStrong.displayName = "DelacourUI.Text.Strong";

/** Inline emphasis by slant. Inherits size, weight and colour from the text around it. */
function TextEmphasis(props: TextPresetProps): ReactElement {
	return <TextRoot variant="emphasis" {...props} />;
}
TextEmphasis.displayName = "DelacourUI.Text.Emphasis";

/**
 * A tappable run of text. `onPress` rides through from React Native's own
 * `TextProps` and works on a nested `<Text>` on both platforms.
 *
 * Painted with `info`, not `primary`: `--color-primary` is the primary surface
 * colour and sits within a shade of `foreground` in both themes.
 */
function TextLink(props: TextPresetProps): ReactElement {
	return <TextRoot accessibilityRole="link" variant="link" {...props} />;
}
TextLink.displayName = "DelacourUI.Text.Link";

/**
 * Inline code, monospaced on a muted background.
 *
 * Padded and rounded only when it stands alone. A nested `<Text>` is laid out
 * by the platform's text engine rather than by Yoga — an `NSAttributedString`
 * run on iOS, a `Span` on Android — and both ignore padding, margin and border
 * radius outright, so only the background survives. For a code *block*, wrap it:
 *
 * @example
 * <View className="rounded-lg bg-muted p-3">
 *   <Text.Code className="bg-transparent" size="sm">bun run gen-exports</Text.Code>
 * </View>
 */
function TextCode(props: TextPresetProps): ReactElement {
	return <TextRoot variant="code" {...props} />;
}
TextCode.displayName = "DelacourUI.Text.Code";

/**
 * A piece of text, and the type scale the whole library draws from.
 *
 * Every `Text` publishes its own resolved classes to its subtree, so a nested
 * `<Text>` inherits the treatment around it and overrides only the axes it
 * names — which is what React Native does natively with a nested `<Text>`'s
 * style, and what Uniwind breaks by compiling each `className` independently.
 *
 * Precedence, weakest first: the base treatment, the inherited class, this
 * text's own named axes, then its `className`.
 *
 * Anything can publish into that cascade, not just a `Text` — `Button` wraps its
 * children in a `TextClassProvider` carrying the label's treatment, so a bare
 * `<Text>` composed into one needs nothing at the call site. The same idea as
 * `IconDefaultsProvider`, and the same single path.
 *
 * OS font scaling is respected and capped at {@link TEXT_MAX_FONT_SIZE_MULTIPLIER};
 * both `allowFontScaling` and `maxFontSizeMultiplier` remain overridable.
 *
 * @example
 * <Text.Title>Total <Text color="muted">USD</Text></Text.Title>
 *
 * @example
 * <Text.Paragraph>
 *   Run <Text.Code>bun test</Text.Code> before you <Text.Strong>commit</Text.Strong>.
 * </Text.Paragraph>
 *
 * @example
 * // No `asChild`: a Text's child is usually a string, which `Slot` cannot take
 * // props. Read the cascade directly instead.
 * <Animated.Text className={useTextClass()} style={fadeStyle} />
 */
export const Text = Object.assign(TextRoot, {
	/** A screen's one hero line — 30pt bold. Announced as a heading. */
	Display: TextDisplay,
	/** A screen or card title — 24pt bold. Announced as a heading. */
	Title: TextTitle,
	/** A section heading — 20pt semibold. Announced as a heading. */
	Header: TextHeader,
	/** The secondary line under a title — 18pt muted. Not a fourth heading level. */
	Subheader: TextSubheader,
	/** A block of prose — 16pt. The same treatment a bare `<Text>` renders. */
	Paragraph: TextParagraph,
	/** A control label or compact UI string — 14pt medium. */
	Label: TextLabel,
	/** Supporting copy — 14pt on the muted token. */
	Caption: TextCaption,
	/** An eyebrow above a section — 12pt semibold, uppercase, muted. */
	Overline: TextOverline,
	/** Inline emphasis by weight. Inherits size and colour from the text around it. */
	Strong: TextStrong,
	/** Inline emphasis by slant. Inherits size, weight and colour from the text around it. */
	Emphasis: TextEmphasis,
	/** A tappable run of text, on the `info` token. Takes `onPress`. */
	Link: TextLink,
	/** Inline code, monospaced. Padded only when it stands alone. */
	Code: TextCode,
	displayName: "DelacourUI.Text",
});

import type { VariantProps } from "tailwind-variants";
import { cn } from "@registry/lib/cn";
import { tv } from "@registry/lib/tv";

/**
 * The named text roles, block presets first and largest first.
 *
 * Order carries meaning for the block half — the tests read it to assert the
 * type scale descends — so a new block role goes in at its step rather than on
 * the end.
 */
export const TEXT_VARIANTS = [
	"display",
	"title",
	"header",
	"subheader",
	"paragraph",
	"label",
	"caption",
	"overline",
	"strong",
	"emphasis",
	"link",
	"code",
] as const;

/**
 * Presets that emit only a delta — a weight, a slant, a decoration, a family —
 * and inherit size, colour and weight from the `Text` they sit inside.
 *
 * This is what makes `<Text.Paragraph>Hi <Text.Strong>there</Text.Strong></Text.Paragraph>`
 * come out at the paragraph's size and colour instead of snapping back to a
 * base of its own.
 */
export const TEXT_INLINE_VARIANTS = ["strong", "emphasis", "link", "code"] as const;

export const TEXT_SIZES = ["xs", "sm", "md", "lg", "xl", "2xl", "3xl"] as const;
export const TEXT_WEIGHTS = ["normal", "medium", "semibold", "bold"] as const;
export const TEXT_COLORS = ["default", "muted", "danger", "success", "warning", "info"] as const;
export const TEXT_ALIGNS = ["left", "center", "right"] as const;
export const TEXT_TRANSFORMS = ["none", "uppercase", "lowercase", "capitalize"] as const;

export type TextVariant = (typeof TEXT_VARIANTS)[number];
export type TextInlineVariant = (typeof TEXT_INLINE_VARIANTS)[number];
export type TextSize = (typeof TEXT_SIZES)[number];
export type TextWeight = (typeof TEXT_WEIGHTS)[number];
export type TextColor = (typeof TEXT_COLORS)[number];
export type TextAlign = (typeof TEXT_ALIGNS)[number];
export type TextTransform = (typeof TEXT_TRANSFORMS)[number];

/**
 * The treatment a `Text` falls back to on every axis nothing else names.
 *
 * First in {@link resolveTextClass}'s chain and therefore the weakest source, so
 * it never fights an inherited class or a named axis. It is applied
 * unconditionally — including inside a nested `Text` — and that is deliberate.
 *
 * For a nested `Text` it is a no-op: the parent's resolved class came out of
 * this same function and already names all three axes, so tailwind-merge drops
 * every class here. It only does work under a *partial* provider — a `Button`
 * publishing nothing but `text-primary-foreground`, say. Guarding it behind "am
 * I nested" would leave that `Text` with a colour and no size at all, silently
 * collapsing to React Native's own 14pt default.
 *
 * It names exactly the three axes React Native inherits natively and cannot
 * default sensibly on its own: weight, size, colour.
 */
export const TEXT_BASE_CLASS = "font-normal text-base text-foreground";

/**
 * Cap on OS font scaling.
 *
 * Accessibility text sizes are respected — `allowFontScaling` is left at React
 * Native's default — but the library's fixed-height chrome cannot grow with
 * them: `h-button-sm|md|lg` are hard 36/44/52pt and `h-navbar-row` is 56pt, so
 * an uncapped multiplier clips a label rather than enlarging it.
 */
export const TEXT_MAX_FONT_SIZE_MULTIPLIER = 1.4;

/**
 * Styling for one piece of text, on six independent axes.
 *
 * ## Order is the design
 *
 * `tv` emits variants in the order their keys are declared here, then the
 * compound variants, then the caller's `className`. `variant` is FIRST because
 * a preset is the weakest named source: `<Text.Header size="sm">` has to come
 * out at 14pt. The axes after it touch different tailwind-merge groups, so
 * their order relative to each other means nothing.
 *
 * ## No `defaultVariants`, on purpose
 *
 * A `defaultVariants: { size: "md" }` would emit `text-base` from THIS call,
 * after `variant` and therefore ahead of it in the merge — every preset's size
 * would be overwritten by the default. More importantly an axis the caller did
 * not name has to emit *nothing*, so it falls through to the class the
 * enclosing `Text` published. That is what reproduces React Native's own
 * cascade. `iconVariants` avoids the same trap for the same reason; the
 * fallback lives in {@link TEXT_BASE_CLASS} instead.
 *
 * ## A variant names type, never a line height
 *
 * tailwind-merge lists `leading` among `font-size`'s conflicting groups, so a
 * `text-lg` from the `size` axis silently strips a `leading-6` written beside a
 * `text-base` here — no error, just a paragraph that loses its leading the
 * moment someone resizes it. Tailwind v4's `--text-*--line-height` companions
 * survive `tokens.css`'s size-only overrides, so every step already carries a
 * paired leading. If prose ever needs its own, add a `--text-paragraph` /
 * `--text-paragraph--line-height` *pair* in `tokens.css` and register the
 * bespoke name in `tokens.ts` — one utility carrying both.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot
 * parse React Native's Flow-typed source. See AGENTS.md.
 */
export const textVariants = tv({
	variants: {
		variant: {
			display: "font-bold text-3xl text-foreground",
			title: "font-bold text-2xl text-foreground",
			header: "font-semibold text-xl text-foreground",
			// A step down from the title it sits under, not a fourth heading
			// level — which is why it is muted and carries no weight of its own.
			subheader: "text-lg text-muted-foreground",
			paragraph: "text-base text-foreground",
			label: "font-medium text-sm text-foreground",
			caption: "text-sm text-muted-foreground",
			overline: "font-semibold text-muted-foreground text-xs uppercase tracking-wide",
			// The four below emit a delta and nothing else. See TEXT_INLINE_VARIANTS.
			strong: "font-semibold",
			emphasis: "italic",
			// `text-info`, never `text-primary`. `--color-primary` is the primary
			// SURFACE — #262626 light, #f5f5f5 dark — so a link painted with it
			// would be indistinguishable from the foreground it sits in.
			link: "text-info underline",
			code: "bg-muted font-mono",
		},
		// The empty branches are load-bearing typing, not placeholders: a map with
		// only `true` types the prop as `true` rather than `boolean`. The compound
		// below matches without them — `tv` compares against `defaultVariants` plus
		// props and never reads this map. See the note in button.variants.ts.
		isNested: { true: "", false: "" },
		size: {
			xs: "text-xs",
			sm: "text-sm",
			// `md` rather than Tailwind's own `base`, so one step name means "the
			// default step" across Icon, Spinner, Button, ListGroup and Text. The
			// token underneath is still `--text-base`.
			md: "text-base",
			lg: "text-lg",
			xl: "text-xl",
			"2xl": "text-2xl",
			"3xl": "text-3xl",
		},
		weight: {
			normal: "font-normal",
			medium: "font-medium",
			semibold: "font-semibold",
			bold: "font-bold",
		},
		// Page-level text colours only. Text drawn ON a coloured surface is that
		// surface component's job — BUTTON_FOREGROUND_TOKEN already maps a variant
		// to its foreground, and a second copy of that map here could drift from
		// it. A caller on a coloured surface writes the utility directly.
		color: {
			default: "text-foreground",
			muted: "text-muted-foreground",
			danger: "text-danger",
			success: "text-success",
			warning: "text-warning",
			info: "text-info",
		},
		// `left`/`right`, never `start`/`end`: React Native's `textAlign` accepts
		// auto | left | right | center | justify and nothing else, so Tailwind v4's
		// logical-property utilities would resolve to a value RN rejects.
		align: { left: "text-left", center: "text-center", right: "text-right" },
		transform: {
			// `normal-case` rather than an empty string, so `transform="none"` can
			// actually clear an inherited or preset `uppercase`.
			none: "normal-case",
			uppercase: "uppercase",
			lowercase: "lowercase",
			capitalize: "capitalize",
		},
	},
	compoundVariants: [
		// A standalone `Text.Code` is an ordinary Yoga box and takes padding. A
		// NESTED one is a run inside the platform text engine — iOS lays it out as
		// an NSAttributedString, Android as a Span — and both ignore padding,
		// margin and border radius on an inner `<Text>` outright. Only the
		// background survives, drawn tight to the glyphs with square corners.
		{ variant: "code", isNested: false, class: "rounded-md px-1.5 py-0.5" },
	],
});

/** Whether a preset emits only a delta and inherits the rest from the `Text` above it. */
export function isInlineTextVariant(variant: TextVariant): boolean {
	return (TEXT_INLINE_VARIANTS as readonly string[]).includes(variant);
}

/**
 * Whether a `Text` with these children can hold a nested `Text` at all.
 *
 * A string or number child has no descendant component, so nothing below could
 * read the context — publishing it would render a provider element per label
 * for the most-instantiated component in the library. `false` here is provable
 * rather than a guess, which is what makes skipping the provider safe.
 *
 * Deliberately typed on `unknown` rather than `ReactNode`: keeping this module
 * free of even a type import is what lets `bun test` reach it.
 */
export function canNestText(children: unknown): boolean {
	return typeof children !== "string" && typeof children !== "number";
}

/**
 * The class chain that styles one piece of text, weakest source first.
 *
 * | Source | How it wins |
 * | --- | --- |
 * | {@link TEXT_BASE_CLASS} | first in the chain |
 * | the class inherited from the enclosing `Text` or `TextClassProvider` | second |
 * | this `Text`'s own named axes | third |
 * | the caller's `className` | last |
 *
 * This is what replaces React Native's native text inheritance. Natively a
 * nested `<Text>` inherits the parent's *style object* and overrides only the
 * keys it sets; here every `Text` compiles its own className, so the parent's
 * resolved class has to be threaded through and beaten per-axis rather than
 * wholesale. The chain does that: an axis the child names wins, an axis it
 * leaves alone falls through.
 *
 * The property that makes nesting correct is a fixpoint — for every `x` this
 * function can produce, `resolveTextClass({ inherited: x })` is exactly `x`, at
 * any depth. The tests assert it across the matrix.
 *
 * Precedence is the ladder `Icon` and `Spinner` already follow, so a `Text`
 * composed into a `Button` matches it without being told to. See
 * `resolveIconSizeClass`.
 *
 * Pure, so the whole ladder is reachable from `bun test`. See AGENTS.md.
 */
export function resolveTextClass({
	align,
	className,
	color,
	inherited,
	isNested = false,
	size,
	transform,
	variant,
	weight,
}: {
	align?: TextAlign;
	className?: string;
	color?: TextColor;
	inherited?: string;
	isNested?: boolean;
	size?: TextSize;
	transform?: TextTransform;
	variant?: TextVariant;
	weight?: TextWeight;
}): string {
	return cn(
		TEXT_BASE_CLASS,
		inherited,
		textVariants({ align, color, isNested, size, transform, variant, weight }),
		className
	);
}

export type TextVariantProps = VariantProps<typeof textVariants>;
